		tgt.[defaultmailbox_entitytype] = stg.[defaultmailbox_entitytype],
		tgt.[defaultmailboxname] = stg.[defaultmailboxname],
		tgt.[description] = stg.[description],
		tgt.[emailaddress] = stg.[emailaddress],
		tgt.[emailpassword] = stg.[emailpassword],
		tgt.[emailrouteraccessapproval] = stg.[emailrouteraccessapproval],
		tgt.[emailusername] = stg.[emailusername],
		tgt.[entityimage_timestamp] = stg.[entityimage_timestamp],
		tgt.[entityimage_url] = stg.[entityimage_url],
		tgt.[entityimageid] = stg.[entityimageid],
		tgt.[exchangerate] = stg.[exchangerate],
		tgt.[ignoreunsolicitedemail] = stg.[ignoreunsolicitedemail],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[incomingemaildeliverymethod] = stg.[incomingemaildeliverymethod],
		tgt.[incomingemailfilteringmethod] = stg.[incomingemailfilteringmethod],
		tgt.[isemailaddressapprovedbyo365admin] = stg.[isemailaddressapprovedbyo365admin],
		tgt.[isfaxqueue] = stg.[isfaxqueue],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[msdyn_assignmentinputcontractid] = stg.[msdyn_assignmentinputcontractid],
		tgt.[msdyn_assignmentinputcontractid_entitytype] = stg.[msdyn_assignmentinputcontractid_entitytype],
		tgt.[msdyn_assignmentinputcontractidname] = stg.[msdyn_assignmentinputcontractidname],
		tgt.[msdyn_assignmentstrategy] = stg.[msdyn_assignmentstrategy],
		tgt.[msdyn_isdefaultqueue] = stg.[msdyn_isdefaultqueue],
		tgt.[msdyn_isomnichannelqueue] = stg.[msdyn_isomnichannelqueue],
		tgt.[msdyn_maxqueuesize] = stg.[msdyn_maxqueuesize],
		tgt.[msdyn_operatinghourid] = stg.[msdyn_operatinghourid],
		tgt.[msdyn_operatinghourid_entitytype] = stg.[msdyn_operatinghourid_entitytype],
		tgt.[msdyn_operatinghouridname] = stg.[msdyn_operatinghouridname],
		tgt.[msdyn_priority] = stg.[msdyn_priority],
		tgt.[msdyn_queuetype] = stg.[msdyn_queuetype],
		tgt.[msdyn_uniquename] = stg.[msdyn_uniquename],
		tgt.[name] = stg.[name],
		tgt.[numberofitems] = stg.[numberofitems],
		tgt.[numberofmembers] = stg.[numberofmembers],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationid_entitytype] = stg.[organizationid_entitytype],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[outgoingemaildeliverymethod] = stg.[outgoingemaildeliverymethod],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[ownerid] = stg.[ownerid],
		tgt.[ownerid_entitytype] = stg.[ownerid_entitytype],
		tgt.[owneridname] = stg.[owneridname],
		tgt.[owneridtype] = stg.[owneridtype],
		tgt.[owneridyominame] = stg.[owneridyominame],
